SELECT COUNT(*)
  FROM md_content_report
 WHERE target_type = #{targetType}
   AND target_id = #{targetId}


        AND reporter_user_id = #{userId}


        AND reporter_anon_id = #{anonId}

SELECT r.no , r.target_type , r.target_id , r.reason_code , r.detail , r.target_snapshot , r.reporter_user_id , r.status , r.handled_by , r.handled_at , r.created_at , (SELECT COUNT(*) FROM md_content_report c WHERE c.target_type = r.target_type AND c.target_id = r.target_id) AS report_count FROM md_content_report r
r.status = #{status}
ORDER BY r.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE md_content_report
   SET status = #{status}
     , handled_by = #{handledBy}
     , handled_at = NOW()
 WHERE no = #{no}
